bool cMenuClanMemberList::isMyClan() {
    if (mClanId != 0) {
        if (static_cast<sNetworkExt*>(sNetwork::getInstance())->isBelongClan()) {
            u32 t0 = mClanId;
            if (t0 != static_cast<sNetworkExt*>(sNetwork::getInstance())->getMyClanId()) {
                return false;
            } else {
                return true;
            }
        } else {
            return false;
        }
    } else {
        return true;
    }
}

